def subtract(a, b):
    """
    Returns points covered by some interval in a and by no interval in b.
    Result is a sorted list of disjoint [start, end) intervals.
    """
    # Filter out empty intervals and merge overlapping ones
    def merge_intervals(intervals):
        if not intervals:
            return []

        # Filter empty intervals and sort
        valid = [interval for interval in intervals if interval[0] < interval[1]]
        if not valid:
            return []

        valid.sort()
        merged = [valid[0]]

        for current in valid[1:]:
            last = merged[-1]
            if current[0] <= last[1]:
                # Overlapping or touching, merge them
                merged[-1] = [last[0], max(last[1], current[1])]
            else:
                # Non-overlapping, add as new interval
                merged.append(current)

        return merged

    # Merge both a and b
    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    if not a_merged:
        return []

    if not b_merged:
        return a_merged

    # Subtract b from a
    result = []

    for a_start, a_end in a_merged:
        current_intervals = [[a_start, a_end]]

        # Subtract each b interval from current_intervals
        for b_start, b_end in b_merged:
            new_intervals = []
            for curr_start, curr_end in current_intervals:
                # No overlap
                if curr_end <= b_start or curr_start >= b_end:
                    new_intervals.append([curr_start, curr_end])
                else:
                    # There's overlap, keep the non-overlapping parts
                    if curr_start < b_start:
                        new_intervals.append([curr_start, b_start])
                    if curr_end > b_end:
                        new_intervals.append([b_end, curr_end])
            current_intervals = new_intervals

        result.extend(current_intervals)

    # Merge adjacent intervals in result
    if not result:
        return []

    result.sort()
    merged_result = [result[0]]

    for current in result[1:]:
        last = merged_result[-1]
        if current[0] <= last[1]:
            merged_result[-1] = [last[0], max(last[1], current[1])]
        else:
            merged_result.append(current)

    return merged_result

